public static string Band(int percent) => percent switch
{
    < 0 or > 100 => throw new ArgumentOutOfRangeException(nameof(percent)),
    < 50 => "fail",
    < 70 => "pass",
    < 90 => "merit",
    _ => "distinction"
};

public static decimal Delta(string[] row) => row switch
{
    [_, "DEPOSIT", _, var amount] => decimal.Parse(amount),
    [_, "WITHDRAWAL", .., var amount] => -decimal.Parse(amount),
    [_, "FEE", var fee] => -decimal.Parse(fee),
    _ => throw new FormatException($"Row not recognized: {string.Join(',', row)}")
};

public sealed record AuthToken(string Scheme, string? Version, DateTimeOffset? ExpiresAt);

public static bool IsUsableBearer(AuthToken token, DateTimeOffset utc) =>
    token is { Scheme: "Bearer", ExpiresAt: DateTimeOffset exp } && exp > utc;

public static bool HasVersion(AuthToken token) =>
    token is { Version: not null };

public sealed record WireToken(string Scheme, string? Issuer, int? Exp);

string Classify(WireToken t) => t switch
{
    { Scheme: "LTI", Issuer: not null } => "lti",
    { Scheme: "Bearer", Exp: > 0 } => "oidc",
    { Scheme: "ApiKey" } => "apikey",
    _ => throw new ArgumentException("unknown wire shape", nameof(t))
};

// List pattern on CSV row — ragged import guard:
bool IsValidRow(string[] cols) => cols switch
{
    [_, "SKU", .., var price] when decimal.TryParse(price, out _) => true,
    _ => false
};
